import { stdout } from std.io;
class Animal {
    construct() { }
    speak(): String { return "..."; }
}
class Dog extends Animal {
    construct() { super(); }
    #override speak(): String { return "woof"; }
}
fn main(): Void {
    mut a: Animal = Dog();
    mut d: Dog? = a as ? Dog;
    match d {
        null => stdout.println("no dog"),
        dog => stdout.println(dog.speak()),
    }
}
